import{c as e,Q as t,j as a,m as i}from"./chunks/framework.DOi4mjdC.js";const n="/assets/%E7%AE%97%E5%AD%90%E5%BC%80%E5%8F%91%E7%AB%AF%E5%88%B0%E7%AB%AF%E6%B5%81%E7%A8%8B-34.C4U4-8vt.png",A=JSON.parse('{"title":"概述","description":"","frontmatter":{},"headers":[{"level":1,"title":"概述","slug":"概述"}],"relativePath":"guide/编程指南/高级编程/高级特性/算子入图开发/概述.md","filePath":"guide/编程指南/高级编程/高级特性/算子入图开发/概述.md"}'),r={name:"guide/编程指南/高级编程/高级特性/算子入图开发/概述.md"};function h(s,l,o,p,m,c){return t(),a("div",null,[...l[0]||(l[0]=[i('<h1 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h1><p>图模式是神经网络模型的一种运行模式，在图模式下用户首先将模型的计算过程构造成一张图，然后通过GE将图下发到昇腾硬件执行。相对于单个算子依次下发的方式，图模式下，GE可以通过计算图优化、多流并行、内存复用、模型下沉等技术手段，加速模型执行效率，减少模型内存占用。</p><p>算子入图的开发流程如下图所示：算子工程创建完成后，基于工程代码框架完成算子原型定义、kernel侧算子实现、host侧tiling实现并完成算子入图开发，通过工程编译脚本完成算子的编译部署，之后即可基于图IR执行算子，比如IR构图的方式调用自定义算子。该开发流程以<a href="./../Aclnn算子工程化开发/概述.html">工程化算子开发</a>为基础，除了需要提供工程化算子开发中的算子实现文件外，还需要额外交付算子入图的代码文件。</p><p><img src="'+n+'" alt=""></p><ol><li><p>环境准备。</p><ol><li>CANN软件安装请参考<a href="./../../../../入门教程/环境准备.html">环境准备</a>。</li><li><a href="./../Aclnn算子工程化开发/创建算子工程.html">创建算子工程</a>。使用msOpGen工具创建算子开发工程。</li></ol></li><li><p>算子实现。</p><ul><li><a href="./../Aclnn算子工程化开发/算子原型定义.html">算子原型定义</a>。通过原型定义来描述算子输入输出、属性等信息以及算子在AI处理器上相关实现信息，并关联tiling实现等函数。</li><li>Kernel侧算子实现和host侧tiling实现请参考<a href="./../../../../算子实践参考/SIMD算子实现/概述.html">SIMD算子实现</a>；工程化算子开发，支持开发者调用Tiling API基于CANN提供的编程框架进行tiling开发，kernel侧也提供对应的接口方便开发者获取tiling参数，具体内容请参考<a href="./../Aclnn算子工程化开发/Kernel侧算子实现.html">Kernel侧算子实现</a>和<a href="./../Aclnn算子工程化开发/Host侧Tiling实现/基本流程.html">Host侧Tiling实现</a>，由此而带来的额外约束也在上述章节说明。</li></ul></li><li><p><a href="./基本开发流程.html">算子入图（GE图）开发</a>。算子入图场景下，需要提供shape推导等算子入图适配函数的实现。</p></li><li><p>编译部署。通过工程编译脚本完成算子的编译部署，分为<a href="./../Aclnn算子工程化开发/算子包编译/算子工程编译.html">算子包编译</a>和<a href="./../Aclnn算子工程化开发/算子动态库和静态库编译.html">算子动态库编译</a>两种方式。</p></li><li><p><a href="./图编译和图执行.html">图编译和图执行</a>：基于图IR执行算子，比如IR构图的方式调用自定义算子。</p></li></ol>',5)])])}const f=e(r,[["render",h]]);export{A as __pageData,f as default};
